import { ReactNode, FC } from 'react';

interface SearchBarProps {
    /** 输入值 (受控) */
    value?: string;
    /** 默认值 (非受控) */
    defaultValue?: string;
    /** 占位文本 */
    placeholder?: string;
    /** 是否显示取消按钮 */
    showCancel?: boolean;
    /** 取消按钮文字 */
    cancelText?: string;
    /** 是否自动聚焦 */
    autoFocus?: boolean;
    /** 是否禁用 */
    disabled?: boolean;
    /** 是否显示清除按钮 */
    clearable?: boolean;
    /** 左侧图标 */
    icon?: ReactNode;
    /** 输入框对齐方式 */
    align?: 'left' | 'center';
    /** 背景色 */
    backgroundColor?: string;
    /** 值变化回调 */
    onChange?: (value: string) => void;
    /** 聚焦回调 */
    onFocus?: (e: unknown) => void;
    /** 失焦回调 */
    onBlur?: (e: unknown) => void;
    /** 搜索回调 */
    onSearch?: (value: string) => void;
    /** 取消回调 */
    onCancel?: () => void;
    /** 清除回调 */
    onClear?: () => void;
    /** 自定义类名 */
    className?: string;
}

declare const SearchBar: FC<SearchBarProps>;

export { SearchBar, SearchBar as default };
export type { SearchBarProps };
